@module library  src=library.lua  loc=196  mode=chunk  self=lib
@deps cm, synthetic

# Imports
  @require util = 'util'  @ 4

# Private state
  @state lib = {}  @ 9

# Private functions
  -- Tier reads
  @fn synth(key)  @ 13
  @fn projectTier(key)  @ 14
  @fn libraryTier(key)  @ 15
  @fn factoryTier(key)  @ 16
  @fn sourceOf(key, name)  @ 20-22
      -- Publishable/revertable source for a name: the library copy, never the
      -- project copy. (The factory catalogue is a seed source, not a live source.)
  -- Tier writes
  @fn writeTier(level, key, name, value)  @ 27-31
      -- Read-modify-write a whole tier through one cm:set; cm deep-copies the value in.
  -- Names
  @fn sortedNames(tier, drop)  @ 35-42

# Public API (lib.*)
  @api lib.names(key)  @ 45-51
      @contract  { project, library } sorted names; synthetic floor dropped, no cross-dedup  @ 44
  -- Reads
  @api lib.get(key, name)  @ 56-60
      @contract  resolved deep copy, project over library; nil if neither tier has the name  @ 55
  @api lib.modified(key, name)  @ 63-69
      @contract  true iff a project copy and a same-named source both exist and differ (util.deepEq)  @ 62
  -- Localize / fork
  @api lib.localize(key, name)  @ 74-81
      @contract  copy resolvable entry (library|factory floor) into project; no-op if synthetic/proj copy  @ 73
  @api lib.forkToProject(key, name)  @ 84-87
      @contract  localize then return the editable project copy  @ 83
  -- Author
  @api lib.save(key, name, value)  @ 92-95
      @contract  write a name into the project tier (cm:set deep-copies); synthetic names never  @ 91
  -- Publish / revert
  @api lib.publish(key, name)  @ 100-103
      @contract  project copy -> library tier (deepClone via cm:set); no-op when there is no project copy  @ 99
  @api lib.publishOverwrites(key, name)  @ 106-112
      @contract  true iff publish would overwrite a divergent library copy (both tiers exist and differ)  @ 105
  @api lib.revert(key, name)  @ 115-118
      @contract  library source -> project, discarding drift; no-op if no library copy exists  @ 114
  -- Factory seed / reload
  @api lib.seedIfEmpty(key)  @ 123-131
      @contract  stock an empty library tier from the factory catalogue; no-op once it holds anything  @ 122
  @api lib.reloadPlan(key)  @ 134-147
      @contract  { add = names in factory not library, overwrite = present but divergent }; both sorted  @ 133
  @api lib.factoryOverwrites(key, name)  @ 150-155
      @contract  true iff a factory import would overwrite a divergent library copy (both exist, differ)  @ 149
  @api lib.importFactory(key, name)  @ 158-162
      @contract  copy one factory entry into the library tier (deep-clone via cm:set); synthetic never  @ 157
  -- Tidy / delete
  @api lib.tidy(key, inUse)  @ 167-182
      @contract  drop project entries deepEq their source and not in inUse; single cm:set; returns removed  @ 166
  @api lib.delete(key, level, name)  @ 185-194
      @contract  remove name from tier level (project|global); synthetic names never  @ 184

# Uses (outbound edges)
  @use call    cm:defaultFor  @ factoryTier:16
  @use call    cm:getAt  @ projectTier:14 libraryTier:15 writeTier:28 tidy:169 delete:190
  @use call    cm:set  @ writeTier:30 seedIfEmpty:130 tidy:180 delete:193
  @use call    util.add  @ sortedNames:38 reloadPlan:141,142 tidy:174
  @use call    util.deepEq  @ modified:68 publishOverwrites:111 reloadPlan:142 factoryOverwrites:154 tidy:173
  @use require util  @ <load>:4

# Calls (intra-file)
  @call factoryTier  @ localize:79 seedIfEmpty:127 reloadPlan:138 factoryOverwrites:151 importFactory:160
  @call lib.localize  @ forkToProject:85
  @call libraryTier  @ sourceOf:21 names:49 get:59 localize:79 publishOverwrites:109 seedIfEmpty:124 reloadPlan:135 factoryOverwrites:152
  @call projectTier  @ names:48 get:57 modified:64 localize:76 forkToProject:86 publish:101 publishOverwrites:108
  @call sortedNames  @ names:48,49
  @call sourceOf  @ modified:66 revert:116 tidy:172
  @call synth  @ names:46 localize:75 save:93 seedIfEmpty:125 reloadPlan:136 importFactory:159 delete:189
  @call writeTier  @ localize:80 save:94 publish:102 revert:117 importFactory:161

